package com.securedoc.platform.application.error;

import com.securedoc.platform.domain.error.LvErrorCode;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * Task 0025 step 3: the screen words for codes come from the registry, through one generated file the frontend reads
 * ({@code frontend/securedoc-ui/src/studio/lvErrorCodes.generated.ts}). This test fails when the file is not what the
 * registry and the mapper produce. To write it again: {@code mvn -pl securedoc-application test
 * -Dtest=LvErrorCodeFrontendFileTest -Dlv.codes.write=true}.
 */
class LvErrorCodeFrontendFileTest {

    static final String RELATIVE = "frontend/securedoc-ui/src/studio/lvErrorCodes.generated.ts";

    static Path target() {
        for (Path dir = Path.of("").toAbsolutePath(); dir != null; dir = dir.getParent()) {
            if (Files.isDirectory(dir.resolve("frontend/securedoc-ui/src/studio"))) return dir.resolve(RELATIVE);
        }
        throw new AssertionError("frontend/securedoc-ui/src/studio not found above " + Path.of("").toAbsolutePath());
    }

    @Test
    void generatedFileMatchesTheRegistryAndTheMapper() throws IOException {
        String expected = render();
        Path file = target();
        if (Boolean.getBoolean("lv.codes.write")) {
            Files.writeString(file, expected, StandardCharsets.UTF_8);
        }
        String actual = Files.isRegularFile(file) ? Files.readString(file, StandardCharsets.UTF_8) : "";
        assertEquals(expected, actual.replace("\r\n", "\n"),
                RELATIVE + " is out of date; write it again with -Dlv.codes.write=true");
    }

    static String render() {
        StringBuilder ts = new StringBuilder();
        ts.append("// GENERATED by LvErrorCodeFrontendFileTest from LvErrorCode and LvErrorCodes (backend). Do not edit.\n");
        ts.append("// Source of truth: docs/work/lv-error-codes.md. Regenerate: mvn -pl securedoc-application test\n");
        ts.append("//   -Dtest=LvErrorCodeFrontendFileTest -Dlv.codes.write=true\n\n");
        ts.append("export type LvKind = 'REFUSED' | 'WARNING' | 'WAITING' | 'STOPPED' | 'EXPORT_FAILED' | 'NOT_ALLOWED' | 'SET_UP' | 'SYSTEM';\n\n");
        ts.append("export interface LvCodeEntry {\n");
        ts.append("  code: string;\n  area: string;\n  title: string;\n  description: string;\n  kind: LvKind;\n");
        ts.append("  whoActs: string;\n  httpStatus: number | null;\n  reserved: boolean;\n}\n\n");
        ts.append("/** Every LexaVault error code, in area order. */\n");
        ts.append("export const LV_CODES: Record<string, LvCodeEntry> = {\n");
        for (LvErrorCode code : LvErrorCode.values()) {
            ts.append("  ").append(q(code.code())).append(": { code: ").append(q(code.code()))
                    .append(", area: ").append(q(code.area().name()))
                    .append(", title: ").append(q(code.title()))
                    .append(", description: ").append(q(code.description()))
                    .append(", kind: ").append(q(code.kind().name()))
                    .append(", whoActs: ").append(q(code.whoActs()))
                    .append(", httpStatus: ").append(code.httpStatus().map(String::valueOf).orElse("null"))
                    .append(", reserved: ").append(code.reserved()).append(" },\n");
        }
        ts.append("};\n\n");
        ts.append("/** The code a failure gets when it has none of its own. */\n");
        ts.append("export const LV_FALLBACK = ").append(q(LvErrorCode.FALLBACK.code())).append(";\n\n");
        ts.append("/** Internal identifiers (enum names, errorCode values, categories, reasons) and their LexaVault code. */\n");
        ts.append("export const LV_BY_DETAIL: Record<string, string> = {\n");
        LvErrorCodes.technicalFailureTable().forEach((k, v) -> entry(ts, k.name(), v));
        LvErrorCodes.intakeRejectionTable().forEach((k, v) -> {
            if (!LvErrorCodes.detailTable().containsKey(k.name())) entry(ts, k.name(), v);
            entry(ts, "INTAKE_" + k.name(), v);
        });
        for (Map.Entry<String, LvErrorCode> e : LvErrorCodes.detailTable().entrySet()) entry(ts, e.getKey(), e.getValue());
        ts.append("};\n");
        return ts.toString();
    }

    private static void entry(StringBuilder ts, String key, LvErrorCode code) {
        ts.append("  ").append(key).append(": ").append(q(code.code())).append(",\n");
    }

    private static String q(String value) {
        return "'" + value.replace("\\", "\\\\").replace("'", "\\'") + "'";
    }
}
